SELECT
    w.id,
    w.order_no AS orderNo,
    w.customer_name AS customerName,
    w.customer_mobile AS customerMobile,
    w.barcode,
    w.product_model AS productModel,
    w.main_status AS mainStatus,
    w.current_accept_company_id AS currentAcceptCompanyId,
    cac.company_name AS currentAcceptCompanyName,
    w.assigned_user_id AS assignedUserId,
    su.real_name AS assignedUserName,
    w.has_transfer AS hasTransfer,
    w.transfer_count AS transferCount,
    p.participate_type AS relationType,
    p.is_readonly AS isReadonly,
    w.create_time AS createTime
FROM work_order w
LEFT JOIN sys_company cac ON w.current_accept_company_id = cac.id
LEFT JOIN sys_user su ON w.assigned_user_id = su.id
